mapper.select:
select username, device_id, pre_key_id, public_key, signature, crt_time, upd_time
from t_signed_prekey
where username = #{username,jdbcType=VARCHAR}
  and device_id = #{deviceId,jdbcType=VARCHAR}

select id, username, device_id, pre_key_id, public_key, crt_time, claimed_by, claimed_at
from t_one_time_prekey
where username = #{username,jdbcType=VARCHAR}
  and device_id = #{deviceId,jdbcType=VARCHAR}
  and claimed_by = #{claimedBy,jdbcType=VARCHAR}
order by id asc
limit 1

mapper.update:
update t_one_time_prekey
set claimed_by = #{claimedBy,jdbcType=VARCHAR},
    claimed_at = #{claimedAt,jdbcType=BIGINT}
where id = #{id,jdbcType=BIGINT}
  and username = #{username,jdbcType=VARCHAR}
  and claimed_by is null

update t_one_time_prekey
set claimed_by = null,
    claimed_at = null
where username = #{username,jdbcType=VARCHAR}
  and device_id = #{deviceId,jdbcType=VARCHAR}
  and claimed_by is not null
  and claimed_at is not null
  and claimed_at < #{before,jdbcType=BIGINT}

mapper.delete:
delete from t_one_time_prekey
where username = #{username,jdbcType=VARCHAR}
  and device_id = #{deviceId,jdbcType=VARCHAR}
  and pre_key_id = #{preKeyId,jdbcType=INTEGER}
  and claimed_by = #{claimedBy,jdbcType=VARCHAR}

delete from t_one_time_prekey
where id = #{id,jdbcType=BIGINT}
  and username = #{username,jdbcType=VARCHAR}

